import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HOST_CONNECTIONS_KEY, type HostConnection } from './useHostConnectionsByBuildAndGameId';

async function editHostConnection({
    gameId,
    buildId,
    hostConnection,
}: {
    gameId: string | undefined;
    buildId: string | undefined;
    hostConnection: Partial<Omit<HostConnection, 'uuid'>> & Pick<HostConnection, 'uuid'>;
}): Promise<any> {
    const response = await fetch(`api/games/${gameId}/host-connection`, {
        method: 'PATCH',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            buildId,
            hostConnection,
        }),
    });

    if (!response.ok) {
        let errorData: any;
        try {
            errorData = await response.text();
            errorData = JSON.parse(errorData); // Text only if it fails
        } catch (_error) {}
        throw new Error(errorData.message ? errorData.message : errorData);
    }
    return response.json();
}

export function useHostConnectionEdit(gameId: string | undefined, buildId: string | undefined) {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: editHostConnection,
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: [HOST_CONNECTIONS_KEY, gameId, buildId] });
        },
    });
}
