import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HOST_CONNECTIONS_KEY } from './useHostConnectionsByBuildAndGameId';

async function createHostConnection({
    gameId,
    buildId,
    host,
    ip,
    state,
}: {
    gameId: string | undefined;
    buildId: string | undefined;
    host: string;
    ip: string | undefined;
    state: string | undefined;
}): Promise<any> {
    const response = await fetch(`api/games/${gameId}/host-connection`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            buildId,
            host,
            ip,
            state,
        }),
    });

    if (!response.ok) {
        let errorData: any;
        try {
            errorData = await response.text();
            errorData = JSON.parse(errorData); // Text only if it fails
        } catch (_error) {}
        throw new Error(errorData.message ? errorData.message : errorData);
    }
    return response.json();
}

export function useHostConnectionCreate(gameId: string | undefined, buildId: string | undefined) {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: createHostConnection,
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: [HOST_CONNECTIONS_KEY, gameId, buildId] });
        },
    });
}
