import { DropdownField } from '@gsm-common/components/Form/DropdownField';
import { Button, ButtonGroup, Heading, Modal, Stack } from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { yupResolver } from '@hookform/resolvers/yup';
import { InputField } from '@ncgt/common-ui';
import { useEffect, useMemo, useRef } from 'react';
import { FormProvider, type SubmitHandler, useForm } from 'react-hook-form';
import { type HostConnection, HostConnectionState } from '../hooks/useHostConnectionsByBuildAndGameId';
import { createSchema } from './newNetworkDomainSchama';

export type NewNetworkDomainFormState = {
    host: string;
    ip?: string;
    state: HostConnectionState;
};

export type NewNetworkDomainModalProps = {
    open: boolean;
    onClose: React.MouseEventHandler<HTMLElement> | undefined;
    onSubmit: SubmitHandler<NewNetworkDomainFormState>;
    executing?: boolean;
    hostConnection?: HostConnection;
};

export const NewNetworkDomainModal = (props: NewNetworkDomainModalProps) => {
    const { open, onClose, onSubmit, executing, hostConnection } = props;

    const schema = useMemo(() => createSchema(), []);
    const formRef = useRef<HTMLFormElement>(null);

    const methods = useForm<NewNetworkDomainFormState>({
        mode: 'onChange',
        reValidateMode: 'onChange',
        resolver: yupResolver(schema),
    });

    useEffect(() => {
        if (hostConnection) {
            methods.setValue('host', hostConnection.host);
            methods.setValue('ip', hostConnection.ip);
            methods.setValue('state', hostConnection.state || HostConnectionState.EXCLUDED);
        }
    }, [methods, hostConnection]);

    return (
        <Modal open={open}>
            <Modal.Header>
                <Heading>Add New Domain</Heading>
            </Modal.Header>
            <Modal.Body>
                <FormProvider {...methods}>
                    <form ref={formRef} autoComplete='off' onSubmit={methods.handleSubmit(onSubmit)}>
                        <Stack gap={Dimensions.Space8}>
                            <InputField label='Hostname' name='host' required />
                            <DropdownField
                                label='State'
                                name='state'
                                required
                                options={[
                                    { value: 'ACCEPTED', label: 'Accepted' },
                                    { value: 'EXCLUDED', label: 'Excluded' },
                                ]}
                            />
                            {/* <InputField name='state' label='State' required /> */}
                            <InputField name='ip' label='IP Address' />
                        </Stack>
                    </form>
                </FormProvider>
            </Modal.Body>

            <Modal.Footer>
                <ButtonGroup justifyContent='flex-end'>
                    <Button onClick={onClose} variant='secondary'>
                        Cancel
                    </Button>
                    <Button
                        executing={executing}
                        onClick={() => {
                            formRef.current?.dispatchEvent(new Event('submit', { cancelable: true, bubbles: true }));
                        }}
                    >
                        Submit
                    </Button>
                </ButtonGroup>
            </Modal.Footer>
        </Modal>
    );
};
