import { Layout } from '@gsm-common/components/Layout';
import { paramsObject, useSearchParams } from '@gsm-common/hooks/useSearchParams';
import { keyFromOptions } from '@gsm-common/utils/dropdown/keyFromOptions';
import {
    type DropdownOption,
    Card,
    Dropdown,
    getFuzzyFilterOption,
    Stack,
    Text
} from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { forwardRef, useCallback, useEffect, useMemo, useState } from 'react';
import { DropdownTrigger } from '../Play/components/PageHeader/components/DropdownTrigger';
import { useGameChannels } from '../Play/hooks/useGameChannels';
import styles from './NetworkValidationDashboard.module.css';
import { useBuildSearch } from '@gsm-app/hooks/useBuildSearch';
import { NetworkValidationTable } from './components/NetworkValidationTable';
import { useNetworkReport } from './hooks/useNetworkReport';
import { useHostConnectionsByBuildAndGameId } from './hooks/useHostConnectionsByBuildAndGameId';
import { NetworkSubmitReportButton } from './components/NetworkSubmitReportButton';

type SearchParams = {
    gameId?: string;
    channelName?: string;
    startDate?: string;
    endDate?: string
    networkReport?: string;
};

export const NetworkValidationDashboard = () => {
    const [
        { gameId, networkReport },
        setParams,
    ] = useSearchParams<SearchParams>();

    const {
        gameOptions,
        activeBuild,
        selectedGame,
        selectedChannel,
    } = useGameChannels();

    const [displayName, setDisplayName] = useState<string | undefined>();
    const [selectedBuild, setSelectedBuild] = useState<DropdownOption<string> | undefined>();

    useEffect(() => {
        setDisplayName(displayName ? displayName : activeBuild?.label ?? selectedChannel?.subtitle);
    }, [displayName, selectedChannel, activeBuild?.label]);

    const { data, isLoading } = useBuildSearch(selectedGame?.value, displayName);
    const { hostConnections, isLoading: isLoadingHostConnections, forceRefreshHostConnections } = useHostConnectionsByBuildAndGameId(gameId, selectedBuild?.value);

    const {
        networkReport: submittedNetworkReport
    } = useNetworkReport(gameId, selectedBuild?.value);

    const buildDropdownOptions = useMemo<DropdownOption<string>[]>(() => {
        const builds = data?.data ? data?.data : [];
        return builds.map((buildSearch) => {
            return {
                label: buildSearch.build.displayName,
                value: buildSearch.build.buildId,
                subtitle: buildSearch.channels?.join(', ')
            }
        });
    }, [data]);

    const onFilterOptions = useCallback((searchTerm: string) => {
        return buildDropdownOptions.filter((option: DropdownOption<string>) => {
            return option.label.includes(searchTerm);
        })
    }, [buildDropdownOptions]);

    const onBuildSearchInputChanged = useCallback((searchTerm: string) => {
        setDisplayName(searchTerm);
    }, []);

    const onRefetchTelemetryEvents = useCallback(() => {
        forceRefreshHostConnections();
    }, [forceRefreshHostConnections]);

    // Assign the build from the channel active build if no build was selected
    useEffect(() => {
        // Try to find an option to populate the selected build
        const builds = data?.data ? data?.data : [];
        if (!selectedBuild) {
            for (const build of builds) {
                if (build.build.displayName === `${activeBuild?.label} (${activeBuild?.id})`) {
                    setSelectedBuild({
                        label: build.build.displayName,
                        value: build.build.buildId,
                        subtitle: build.channels?.join(', ')
                    });
                }
            };
        }
    }, [activeBuild, selectedBuild, data?.data]);

    if (networkReport) {
        return (
            <Text>{networkReport}</Text>
        )
    }

    const buildId = useMemo(() => {
        const buildIdMatch = selectedBuild?.label.match(/\(([^)]+)\)/);
        return buildIdMatch ? buildIdMatch[1] : undefined;
    }, [selectedBuild]);

    const buildUUID = useMemo(() => {
        return selectedBuild?.value;
    }, [selectedBuild]);

    return (
        <Layout full>
            <Card fullScreen className={styles.content}>
                <Card.Header className={styles.headerBanner}>

                {/* <Paper elevation={1} className={styles.headerBanner}> */}

                    <Dropdown
                        DropdownTrigger={forwardRef((props: any, ref: any) => (
                            <DropdownTrigger {...props} hideSubtitle ref={ref} />
                        ))}
                        label={`Game ID: ${selectedGame?.value ?? ''}`}
                        groupBy={option => option.group ?? ''}
                        onChange={selected => {
                            if (selected) {
                                setParams(
                                    (prev): SearchParams => {
                                        return {
                                            ...paramsObject(prev),
                                            gameId: selected.value,
                                            channelName: undefined,
                                        };
                                    },
                                    { replace: true },
                                );
                            }
                        }}
                        options={gameOptions}
                        loading={gameOptions.length === 0}
                        value={selectedGame}
                        getOptionValue={option => {
                            if (typeof option === 'string') {
                                return option;
                            }
                            return `${option.group}_${option.value}`;
                        }}
                        searchable={gameOptions.length > 5}
                        filterOptions={getFuzzyFilterOption(gameOptions, {
                            keys: ['label', 'subtitle'],
                            ignoreLocation: true,
                        })}
                        key={`games-${keyFromOptions(gameOptions)}`}

                        style={{ width: 'auto' }}
                        dropdownWidthType='auto'
                    />

                    {/* Build */}
                    <Dropdown
                        DropdownTrigger={forwardRef((props: any, ref: any) => (
                            <DropdownTrigger {...props} hideSubtitle ref={ref} />
                        ))}
                        label='Builds'
                        placeholder='Search build'
                        loading={isLoading}
                        onSearchInputChange={onBuildSearchInputChanged}
                        clearSearchOnSelect={true}
                        debounceTime={250}
                        value={selectedBuild}
                        onChange={(selected: DropdownOption<string> | null) => {
                            if (selected) {
                                setSelectedBuild(selected);
                            }
                        }}
                        options={buildDropdownOptions}
                        searchable={true}
                        style={{ width: 'auto' }}
                        dropdownWidthType={350}
                        filterOptions={onFilterOptions}
                    />
                    {/* </Paper> */}
                </Card.Header>

                <Card.Body style={{flexGrow: 1}}>

                <Stack className={styles.pageContent} gap={Dimensions.Space16}>
                    {/* TODO - Show contextual banner for pending requests */}



                    <NetworkValidationTable
                        gameId={selectedGame?.value}
                        submittedNetworkReport={submittedNetworkReport}
                        buildUUID={buildUUID}
                        buildId={buildId}
                        isLoadingHostConnections={isLoadingHostConnections}
                        hostConnections={hostConnections}
                        onRefetchTelemetryEvents={onRefetchTelemetryEvents}
                    />
                </Stack>

                </Card.Body>

                <Card.Footer>
                    <NetworkSubmitReportButton
                        gameId={selectedGame?.value}
                        buildId={selectedBuild?.value}
                        isLoading={isLoadingHostConnections}
                        hostConnections={hostConnections}
                    />
                </Card.Footer>
            </Card>
        </Layout>
    );
};
