import { Content } from '@gsm-common/components/Content';
import { Layout } from '@gsm-common/components/Layout';
import { useSearchParams } from '@gsm-common/hooks/useSearchParams';
import styles from './NetworkValidationDashboard.module.css';
import { NetworkValidationDashboard } from './NetworkValidationDashboard';
import { NetworkReport } from './components/NetworkReport';

type SearchParams = {
    gameId?: string;
    channelName?: string;
    startDate?: string;
    endDate?: string
    networkReport?: string;
};

export const NetworkingPage = () => {
    const [
        { networkReport },
    ] = useSearchParams<SearchParams>();

    return (
        <Layout full>
            <Content className={styles.content}>
                { networkReport ? (
                    <NetworkReport networkReport={networkReport} />
                ) : (
                    <NetworkValidationDashboard />
                )}
            </Content>
        </Layout>
    );
};
