import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useCallback, useMemo, useState } from 'react';

export const HOST_CONNECTIONS_KEY = 'hostConnections';

export enum HostConnectionState {
    ACCEPTED = 'ACCEPTED',
    EXCLUDED = 'EXCLUDED',
}

export type HostConnectionResponse = {
    data: {
        hostConnections: HostConnection[];
    };
    errors?: {
        title: string;
        detail: string;
    }[];
};

export type HostConnection = {
    uuid?: string;
    host: string;
    gameId: string;
    buildId: string;
    reporter: string;
    ip: string | undefined;
    state: HostConnectionState | undefined;
};

const fetchData = async (gameId: string, buildId: string) => {
    const result = await fetch(`api/games/${gameId}/host-connections/${buildId}`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
    });
    return await result.json();
};

const forceFetchData = async (gameId: string, buildId: string) => {
    const result = await fetch(`api/games/${gameId}/host-connections/${buildId}`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({ force: true }),
    });
    return await result.json();
};

export const useHostConnectionsByBuildAndGameId = (gameId: string | undefined, buildId: string | undefined) => {
    const [isRefreshing, setIsRefreshing] = useState(false);
    const queryKey = useMemo(() => {
        return [HOST_CONNECTIONS_KEY, gameId, buildId];
    }, [gameId, buildId]);

    const queryClient = useQueryClient();
    const query = useQuery<HostConnectionResponse>({
        queryKey,
        staleTime: 0,
        enabled: Boolean(gameId) && Boolean(buildId),
        // biome-ignore lint/style/noNonNullAssertion: <explanation>
        queryFn: async () => fetchData(gameId!, buildId!),
    });

    const hostConnections: HostConnection[] | undefined = useMemo(() => {
        return query.data?.data?.hostConnections;
    }, [query, query.data]);

    const forceRefreshHostConnections = useCallback(async () => {
        setIsRefreshing(true);
        try {
            // biome-ignore lint/style/noNonNullAssertion: <explanation>
            const result = await forceFetchData(gameId!, buildId!);
            queryClient.setQueryData(queryKey, result);
        } catch (error) {
            console.error(error);
        } finally {
            setIsRefreshing(false);
        }
    }, [gameId, buildId, queryKey, queryClient]);

    return {
        ...query,
        isLoading: query.isLoading || isRefreshing,
        forceRefreshHostConnections,
        hostConnections,
    };
};
