import { IconLinkOut } from '@hawkins/assets';
import { Button, ButtonGroup } from '@hawkins/components';
import { useCallback, useMemo } from 'react';
import type { HostConnection, } from '../hooks/useHostConnectionsByBuildAndGameId';
import { useNetworkReportCreate } from '../hooks/useNetworkReportCreate';
import { createError } from '@gsm-common/utils/toast/createError';
import { createSuccess } from '@gsm-common/utils/toast/createSuccess';
import { ROUTE_NETWORK } from '@gsm-app/constants';

export interface SessionEvent {
    events: HostConnection;
}

export interface NetworkSubmitReportButtonProps {
    gameId: string | undefined;
    buildId: string | undefined;
    isLoading: boolean;
    hostConnections: HostConnection[] | undefined;
}

export const NetworkSubmitReportButton = (props: NetworkSubmitReportButtonProps) => {
    const { gameId, buildId, isLoading, hostConnections } = props;
    const { mutateAsync: createNetworkReportAsync, isPending } = useNetworkReportCreate();

    const isSubmissionDisabled = useMemo(() => {
        return !!gameId && !buildId && !isLoading;
    }, [gameId, buildId, isLoading]);

    const onSubmitReport = useCallback(async () => {
        try {
            const result = await createNetworkReportAsync({
                gameId,
                buildId,
                hosts: hostConnections?.map((hostConnection: HostConnection) => {
                    const { host, ip, state } = hostConnection;
                    return { host, ip, state };
                })
            });

            createSuccess({
                title: 'Network Report Submitted',
                body: 'Validated domains have been submitted',
                footer: () => {
                    return (
                        <Button variant='icon' target='_blank' icon={IconLinkOut} href={`${ROUTE_NETWORK}?networkReport=${result.data?.networkReport?.id}`}>
                            Network Report
                        </Button>
                    );
                },
                options: {
                    id: 'network-report-succeeded',
                },
            })
            // biome-ignore lint/suspicious/noExplicitAny: <explanation>
        } catch (error: any) {
            createError({
                title: 'Failed to create networking report',
                body: `${error?.message}`,
                options: {
                    id: 'network-report-error',
                },
            });
        }
    }, [gameId, buildId, hostConnections, createNetworkReportAsync]);

    return (
        <ButtonGroup justifyContent='flex-end'>
            <Button onClick={onSubmitReport} disabled={isSubmissionDisabled} executing={isPending}>
                Submit Report
            </Button>
        </ButtonGroup>
    );
};
