import { useMutation, useQueryClient } from '@tanstack/react-query';
import { NETWORK_REPORT_KEY } from './useNetworkReport';

export type NetworkReportResponse = {
    data: {
        networkReport?: {
            id: string;
        };
    };
    errors?: {
        title: string;
        detail: string;
    }[];
};

async function createNetworkReport({
    gameId,
    buildId,
    hosts,
}: {
    gameId: string | undefined;
    buildId: string | undefined;
    hosts: any;
}): Promise<NetworkReportResponse> {
    const response = await fetch(`api/games/${gameId}/network-report/${buildId}`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            hosts,
        }),
    });

    if (!response.ok) {
        // biome-ignore lint/suspicious/noExplicitAny: <explanation>
        let errorData: any;
        try {
            errorData = await response.text();
            errorData = JSON.parse(errorData); // Text only if it fails
        } catch (_error) {}
        throw new Error(errorData.message ? errorData.message : errorData);
    }
    return response.json();
}

export function useNetworkReportCreate() {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: createNetworkReport,
        onMutate: () => {
            queryClient.invalidateQueries({ queryKey: [NETWORK_REPORT_KEY] });
        },
        onSuccess: (data, { gameId, buildId }) => {
            queryClient.setQueryData([NETWORK_REPORT_KEY, gameId, buildId], data);
        },
    });
}
