import { useQuery } from '@tanstack/react-query';
import { useMemo } from 'react';

export const NETWORK_REPORT_KEY = 'network-report';

// export type NetworkReport = {
//     host: string;
//     gameId: string;
//     buildId: string;
//     ip: string | undefined;
// };

export type NetworkReportResponse = {
    data: {
        networkReport: NetworkReport;
    };
    errors?: {
        title: string;
        detail: string;
    }[];
};

export type NetworkReport = {
    id: string;
    hosts: JSON;
    createdDate: string;
    createdBy?: string;
    gameId?: string;
    buildId?: string;
};

export const useNetworkReportById = (id: string | undefined) => {
    const query = useQuery<NetworkReportResponse>({
        queryKey: [NETWORK_REPORT_KEY, id],
        enabled: Boolean(id),
        queryFn: async () => {
            const result = await fetch(`api/network-report/${id}`, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json',
                },
            });
            return await result.json();
        },
    });

    const networkReport = useMemo(() => {
        return query.data?.data?.networkReport;
    }, [query, query.data]);

    return {
        ...query,
        networkReport,
    };
};

export const useNetworkReport = (gameId: string | undefined, buildId: string | undefined) => {
    const query = useQuery<NetworkReportResponse>({
        queryKey: [NETWORK_REPORT_KEY, gameId, buildId],
        enabled: Boolean(gameId) && Boolean(buildId),
        queryFn: async () => {
            const result = await fetch(`api/games/${gameId}/network-report/${buildId}`, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json',
                },
            });
            return await result.json();
        },
    });

    const networkReport = useMemo(() => {
        return query.data?.data?.networkReport;
    }, [query, query.data]);

    return {
        ...query,
        networkReport,
    };
};
