import { Badge, type BadgeDropdownOption, Divider, Heading, Loader, Stack, Text } from '@hawkins/components';
import {
    Table,
    type TypeColumn,
} from '@hawkins/table';
import { Dimensions } from '@hawkins/variables';
import { Helmet } from 'react-helmet';
import { type HostConnection, HostConnectionState } from '../hooks/useHostConnectionsByBuildAndGameId';
import { useNetworkReportById } from '../hooks/useNetworkReport';
import style from './NetworkReport.module.css';

export interface NetworkReportProps {
    networkReport: string | undefined;
}

const stateDropdownOptions: BadgeDropdownOption<HostConnectionState>[] = [
    { color: 'COMPLETE', label: 'Accepted', value: HostConnectionState.ACCEPTED },
    { color: 'UNKNOWN', label: 'Excluded', value: HostConnectionState.EXCLUDED },
];

const userLocale = navigator.language || 'en-US';
const dateFormat = new Intl.DateTimeFormat(userLocale, { dateStyle: 'medium' });

export const NetworkReport = (props: NetworkReportProps) => {
    const { networkReport } = props;
    const { networkReport: networkReportData, isLoading } = useNetworkReportById(networkReport);

    const hostConnections: any = networkReportData?.hosts || [];
    const networkValidationColumns: TypeColumn[] = [
        {
            name: 'host',
            header: 'Hostname',
            sortable: false,
            flex: 1
        },
        {
            name: 'ip',
            header: 'IP Address',
            sortable: false,
            flex: 1
        },
        {
            name: 'state',
            header: 'State',
            sortable: false,
            flex: 1,
            render: ({ data }: { data: HostConnection }) => {
                const value = stateDropdownOptions.find((badge) => {
                    return badge.value === data.state;
                }) || stateDropdownOptions[1];
                return (
                    <Badge color={value.color}>
                        {value.label}
                    </Badge>
                )
            },
        },
    ];

    return (
        <>
            <Helmet>
                <title>{`Network Report${networkReportData?.gameId ? ` - ${networkReportData?.gameId}`: ''}`}</title>
            </Helmet>
            {isLoading ? (
                <Loader variant='linear' />
            ) : (
                <Stack className={style.networkReportContent} classes={{ root: style.networkReportRoot }}>

                    <Heading>Network Report</Heading>
                    <Stack gap={Dimensions.Space12} orientation='horizontal'>
                        {networkReportData?.gameId && (
                            <Text
                                colorVariant='faded'
                                style={{
                                    marginTop: Dimensions.Space4,
                                    textAlign: 'right',
                                }}
                            >
                                Game Id: {networkReportData.gameId}
                            </Text>
                        )}
                    </Stack>

                    <Stack gap={Dimensions.Space12} orientation='horizontal'>
                        {networkReportData?.createdDate && (
                            <Text
                                colorVariant='faded'
                                style={{
                                    marginTop: Dimensions.Space4,
                                    textAlign: 'right',
                                }}
                            >
                                {dateFormat.format(new Date(networkReportData.createdDate))}
                            </Text>
                        )}

                        {networkReportData?.createdDate && networkReportData?.createdBy && (
                            <Divider variant='vertical' />
                        )}

                        {networkReportData?.createdBy && (
                            <Text
                                colorVariant='faded'
                                style={{
                                    marginTop: Dimensions.Space4,
                                    textAlign: 'right',
                                }}
                            >
                                {networkReportData.createdBy}
                            </Text>
                        )}
                    </Stack>

                    <Table<HostConnection>
                        style={{ minHeight: Dimensions.RawSize448, marginTop: Dimensions.Space16 }}
                        showColumnMenuTool={false}
                        loading={isLoading}
                        disableTableHeaderTooltip
                        idProperty='id'
                        columns={networkValidationColumns}
                        dataSource={hostConnections}
                    >
                    </Table>
                </Stack>

            )}
        </>
    );
};
