import { IconCircleI, IconLinkOut, IconMenu, IconPencil, IconPlus, IconRefresh, IconTrashCan, IconUser } from '@hawkins/assets';
import { type BadgeDropdownOption, BadgeDropdownTrigger, Button, ButtonGroup, Dropdown, Heading, Menu, MenuItem, Stack, Text, Tooltip } from '@hawkins/components';

import {
    AllCommunityModule,
    type ColDef,
    type ColGroupDef,
    ColumnsToolPanelModule,
    FiltersToolPanelModule,
    type ICellRendererParams,
    MenuModule,
    SetFilterModule,
    SideBarModule,
    TableNext,
} from '@hawkins/table-next';

import { Dimensions } from '@hawkins/variables';
import { useQueryClient } from '@tanstack/react-query';
import { useCallback, useMemo, useState } from 'react';
import { HOST_CONNECTIONS_KEY, type HostConnection, HostConnectionState, useHostConnectionsByBuildAndGameId } from '../hooks/useHostConnectionsByBuildAndGameId';
import { type NewNetworkDomainFormState, NewNetworkDomainModal } from './NewNetworkDomainModal';
import { useHostConnectionCreate } from '../hooks/useHostConnectionCreate';
import { isValidUUID } from '@gsm-app/utils/uuid';
import { PAGINATION_OPTIONS, PAGINATION_PAGE_SIZE, ROUTE_NETWORK, ROUTE_SESSIONS } from '@gsm-app/constants';
import { useHostConnectionDelete } from '../hooks/useHostConnectionDelete';
import { useHostConnectionEdit } from '../hooks/useHostConnectionEdit';
import type { NetworkReport } from '../hooks/useNetworkReport';

export interface SessionEvent {
    events: HostConnection;
}

export interface NetworkValidationTableProps {
    gameId: string | undefined;
    buildId: string | undefined;
    buildUUID: string | undefined;
    submittedNetworkReport: NetworkReport | undefined;
    isLoadingHostConnections: boolean;
    hostConnections?: HostConnection[];
    onRefetchTelemetryEvents?: () => void;
}

const stateDropdownOptions: BadgeDropdownOption<HostConnectionState>[] = [
    { color: 'COMPLETE', label: 'Accepted', value: HostConnectionState.ACCEPTED },
    { color: 'UNKNOWN', label: 'Excluded', value: HostConnectionState.EXCLUDED },
];

export const NetworkValidationTable = (props: NetworkValidationTableProps) => {
    const { gameId, buildId, isLoadingHostConnections, hostConnections: telemetryHostConnections, onRefetchTelemetryEvents, submittedNetworkReport } = props;
    const { isLoading, hostConnections = [] } = useHostConnectionsByBuildAndGameId(gameId, buildId);
    const [isNewDomainModalOpen, setIsNewDomainModalOpen] = useState(false);
    const [editedHostConnection, setEditedHostConnection] = useState<HostConnection | undefined>();
    const queryClient = useQueryClient();
    const { mutateAsync: editHostConnectionAsync, isPending: isEditPending } = useHostConnectionEdit(gameId, buildId);
    const { mutateAsync: createNewDomainAsync, isPending: isCreatePending } = useHostConnectionCreate(gameId, buildId);
    const { mutateAsync: deleteHostConnectionAsync, isPending: isDeletePending } = useHostConnectionDelete(gameId, buildId);

    const modules = useMemo(
        () => [
            AllCommunityModule,
            SetFilterModule,
            MenuModule,
            SideBarModule,
            ColumnsToolPanelModule,
            FiltersToolPanelModule,
        ],
        [],
    );

    const defaultColDef = useMemo<ColDef>(() => {
        return {
            editable: false,
            filter: true,
            floatingFilter: true,
            minWidth: 100,
            resizable: true,
            sortable: true,
        };
    }, []);

    const autoGroupColumnDef = useMemo<ColDef>(() => {
        return {
            cellRendererParams: {
                checkbox: false,
                suppressCount: false,
            },
            headerName: 'Group',
            menuTabs: [],
            minWidth: 250,
        };
    }, []);

    const tableLoading = !hostConnections || !telemetryHostConnections || isLoading || isLoadingHostConnections ||
        isCreatePending || isDeletePending || isEditPending;

    const onSubmit = useCallback(async (newDomain: NewNetworkDomainFormState) => {
        const { host, ip, state } = newDomain;

        if (editedHostConnection) {
            const edits = {
                ...editedHostConnection,
                ...newDomain,
            };
            await editHostConnectionAsync({
                gameId,
                buildId,
                hostConnection: {
                    uuid: edits.uuid,
                    host: edits.host,
                    ip: edits.ip,
                    state: edits.state
                }
            });
        } else {
            await createNewDomainAsync({
                gameId,
                buildId,
                host,
                ip,
                state
            });
        }

        setIsNewDomainModalOpen(false);
        setEditedHostConnection(undefined);
    }, [createNewDomainAsync, editHostConnectionAsync, editedHostConnection, gameId, buildId]);

    const onEdit = useCallback(async (hostConnection: HostConnection) => {
        setEditedHostConnection(hostConnection);
        setIsNewDomainModalOpen(true);
    }, []);

    const onDelete = useCallback(async (hostConnection: HostConnection) => {
        const { uuid } = hostConnection;
        await deleteHostConnectionAsync({
            gameId,
            uuid
        });

        queryClient.invalidateQueries({ queryKey: [HOST_CONNECTIONS_KEY, gameId, buildId] });
    }, [deleteHostConnectionAsync, gameId, buildId, queryClient, queryClient.invalidateQueries]);

    const dataSource = useMemo(() => {
        if (!gameId || !buildId) {
            return [];
        }

        return hostConnections;
    }, [gameId, buildId, hostConnections]);

    const columnDefs = useMemo<(ColDef<HostConnection> | ColGroupDef<HostConnection>)[]>(() => {
        return [
            {
                field: 'host',
                headerName: 'Hostname',
                filter: 'agTextColumnFilter',
                flex: 1,
            },
            {
                field: 'ip',
                headerName: 'IP Address',
                filter: 'agTextColumnFilter',
            },
            {
                field: 'state',
                headerName: 'State',
                cellRenderer: (params: ICellRendererParams<HostConnection, HostConnectionState>) => {
                    const value = stateDropdownOptions.find((badge) => {
                        return badge.value === params.value;
                    }) || stateDropdownOptions[1];

                    return (
                        <Dropdown<BadgeDropdownOption<HostConnectionState>, HostConnectionState>
                            DropdownTrigger={BadgeDropdownTrigger}
                            onChange={async (newValue) => {
                                const hostConnection = {
                                    ...params.data,
                                    state: newValue?.value,
                                };
                                await editHostConnectionAsync({
                                    gameId,
                                    buildId,
                                    hostConnection: {
                                        uuid: hostConnection.uuid,
                                        host: hostConnection.host,
                                        ip: hostConnection.ip,
                                        state: hostConnection.state
                                    }
                                });
                            }}
                            options={stateDropdownOptions}
                            value={value}
                        />
                    );
                },
            },
            {
                field: 'reporter',
                headerName: 'Reporter',
                floatingFilter: false,
                sortable: false,
                suppressHeaderContextMenu: true,
                suppressHeaderMenuButton: true,
                suppressHeaderFilterButton: true,
                editable: false,
                maxWidth: Dimensions.RawSize112,
                cellStyle: {
                    overflow: 'hidden',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                },
                cellRenderer: (params: ICellRendererParams<HostConnection, string>) => {
                    const isUUID = params.value ? isValidUUID(params.value) : false;


                    return isUUID ? (
                        <Button
                            variant='icon'
                            compact
                            icon={IconLinkOut}
                            to={`${ROUTE_SESSIONS}/${params.value}`}
                            target='_blank'
                        >
                            Launch Session
                        </Button>
                    ) : (
                        <Tooltip label={params.value || ''} >
                            <IconUser size='small' />
                        </Tooltip>
                    );


                }
            },
            {
                headerName: 'Actions',
                floatingFilter: false,
                sortable: false,
                suppressHeaderContextMenu: true,
                suppressHeaderMenuButton: true,
                suppressHeaderFilterButton: true,
                editable: false,
                maxWidth: Dimensions.RawSize112,
                cellStyle: {
                    overflow: 'hidden',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                },
                cellRenderer: (params: ICellRendererParams<HostConnection, string>) => {
                    const isUUID = params.value ? isValidUUID(params.value) : false;
                    return (
                        <Menu trigger={<IconMenu size='small' />} variant='icon'>
                            <MenuItem disabled={isUUID} key='edit' label='Edit' icon={IconPencil} onClick={() => params.data && onEdit(params.data)} />
                            <MenuItem key='delete' label='Delete' icon={IconTrashCan} onClick={() => params.data && onDelete(params.data)} />
                        </Menu>
                    );
                }
            }
        ];
    }, [buildId, editHostConnectionAsync, gameId, onEdit, onDelete]);

    return (
        <Stack gap={Dimensions.Space16}>
            <NewNetworkDomainModal
                open={isNewDomainModalOpen}
                onClose={() => {
                    setIsNewDomainModalOpen(false);
                }}
                executing={isCreatePending || isEditPending}
                onSubmit={onSubmit}
                hostConnection={editedHostConnection}
            />

            <Stack layout={{ justifyItems: 'space-between', display: 'flex' }} gap={Dimensions.Space12}>
                <Stack layout={{ display: 'flex', alignItems: 'center' }} gap={Dimensions.Space8} orientation='horizontal' style={{ flexGrow: 999 }}>
                    <Heading style={{ whiteSpace: 'nowrap' }}>Network Validation</Heading>
                    <Button
                        compact
                        href='https://docs.netflix.games/release-requirements/grn-current/#173---your-game-must-not-send-user-data-to-unapproved-partners-or-vendors'
                        target='_blank'
                        variant='icon'
                        icon={IconCircleI}
                        style={{ marginLeft: Dimensions.Space4 }}
                    >
                        Documentation
                    </Button>

                    {submittedNetworkReport && (
                        <Button
                            compact
                            tooltipLabel='Open Network Report'
                            variant='secondary'
                            target='_blank'
                            icon={IconLinkOut}
                            href={`${ROUTE_NETWORK}?networkReport=${submittedNetworkReport?.id}`}>
                            Network Report
                        </Button>
                    )}
                </Stack>

                <ButtonGroup style={{ justifyContent: 'end', flexShrink: 999 }}>
                    {(
                        <Button
                            variant='tertiary'
                            icon={IconRefresh}
                            onClick={onRefetchTelemetryEvents}
                            disabled={!gameId || !buildId || isLoading}
                        >
                            Resync domains
                        </Button>
                    )}
                    <Button
                        variant='secondary'
                        icon={IconPlus}
                        onClick={() => {
                            setIsNewDomainModalOpen(true);
                        }}
                        disabled={!gameId || !buildId}
                    >
                        Add Domain
                    </Button>
                </ButtonGroup>
            </Stack>

            <div style={{ height: Dimensions.Size448, width: '100%' }}>
                <TableNext<HostConnection>
                    animateRows={true}
                    loading={tableLoading}
                    autoGroupColumnDef={autoGroupColumnDef}
                    columnDefs={columnDefs}
                    enableCellTextSelection={true}
                    ensureDomOrder={true}
                    defaultColDef={defaultColDef}
                    groupDefaultExpanded={1}
                    modules={modules}
                    noRowsOverlayComponent={() => <Text>No data</Text>}
                    pagination={true}
                    paginationPageSize={PAGINATION_PAGE_SIZE}
                    paginationPageSizeSelector={PAGINATION_OPTIONS}
                    rowData={dataSource}
                    style={{ height: '100%', width: '100%' }}
                />
            </div>
        </Stack>
    );
};
