import * as yup from 'yup';
import { HostConnectionState } from '../hooks/useHostConnectionsByBuildAndGameId';

export const createSchema = (hostNames: string[] | undefined = []) => {
    return yup.object({
        host: yup
            .string()
            .required('Hostname is required')
            .notOneOf(hostNames, 'Hostname already used')
            .max(50)
            .matches(
                /^(([a-zA-Z0-9]|[a-zA-Z0-9][a-zA-Z0-9\-]*[a-zA-Z0-9])\.)*([A-Za-z0-9]|[A-Za-z0-9][A-Za-z0-9\-]*[A-Za-z0-9])$/,
                'Enter a valid hostname',
            ),
        ip: yup.string().matches(/^((25[0-5]|(2[0-4]|1\d|[1-9]|)\d)\.?\b){4}$/, 'Enter a valid IP'),
        state: yup.mixed<HostConnectionState>().oneOf(Object.values(HostConnectionState)).required(),
    });
};
