import { Dropdown, type DropdownOption, FormFieldContainer, type InputProps } from '@hawkins/components';
import { Controller, type FieldPath, type FieldValues, useFormContext } from 'react-hook-form';

export interface DropdownFieldProps<T extends FieldValues> extends Omit<InputProps, 'value'> {
    name: FieldPath<T>;
    label?: string;
    placeholder?: string;
    options: DropdownOption<string>[];
    disabled?: boolean;
    transformValue?: (value: string) => string;
}

export const DropdownField = <T extends FieldValues>(props: DropdownFieldProps<T>) => {
    const {
        name,
        label,
        required,
        placeholder = 'Select an option',
        disabled,
        options,
        transformValue,
        ...rest
    } = props;
    const { control } = useFormContext();
    return (
        <FormFieldContainer>
        <Controller
            name={name}
            control={control}
            render={({ field: { onChange, onBlur, value, name }, fieldState: { error } }) => {
                const selectedValue = options.find((option) => {
                    return option.value === value;
                });
                return (
                    <Dropdown
                    label={label || name}
                    disabled={disabled}
                    requirementType={required ? 'required': 'optional'}
                    id={`${name}-dropdown`}
                    compact
                    placeholder={placeholder}
                    options={options}
                    // biome-ignore lint/suspicious/noExplicitAny: <explanation>
                    onChange={(event: any) => {
                        const newValue = transformValue?.(event?.value) ?? event?.value;
                        const target = { value: newValue };
                        onChange({ currentTarget: target, target, event });
                    }}
                    value={selectedValue}
                    onBlur={onBlur}
                    validationStatus={error ? 'error': undefined}
                    validationMessage={error?.message}
                />
                )
            }}
        />
        </FormFieldContainer>
    );
};
